// Formata o erro de qualquer workflow num alerta pro Thiago.
// Rajadas viram UM alerta agrupado: todo erro entra em giulia_erros_log;
// o aviso (dedup de 30 min por workflow) informa o total da meia hora.
// Erro de TRIGGER (ex.: conexao IMAP do WF18 caindo) chega SEM 'execution' -
// vem em j.trigger.error (mensagem generica do n8n; a causa fica no log do container).
// Reconexao do trigger de e-mail: alerta no maximo 1x a cada 12h (em vez de 30 min).
const j = items[0].json || {};
const wfName = (j.workflow && j.workflow.name) || 'workflow desconhecido';
const trig = (!j.execution && j.trigger) ? j.trigger : null;
const trigErr = (trig && trig.error) || {};
const execId = (j.execution && j.execution.id) || (trig ? 'trigger' : '?');
const node = (j.execution && (j.execution.lastNodeExecuted ||
  (j.execution.error && j.execution.error.node && j.execution.error.node.name))) ||
  (trig ? ('trigger(' + (trig.mode || 'ativo') + ')') : '?');
const causa = trigErr.cause && (trigErr.cause.message || trigErr.cause.code);
const msg = String((j.execution && j.execution.error && j.execution.error.message) ||
  (trigErr.message ? trigErr.message + (causa ? ' | ' + causa : '') : '') || trigErr.description || (trig ? 'erro no trigger sem mensagem' : 'erro desconhecido'))
  .substring(0, 200).replace(/['$]/g, '');   // sem aspas nem cifrao (cifrao quebra a resolucao da expressao no n8n 2.42)
const esc = s => String(s).replace(/'/g, "''");
const wfLike = esc(wfName).replace(/[\\%_]/g, m => '\\' + m);   // escapa % e _ no LIKE (dedup continua valendo)
// reconexao do trigger de e-mail: alerta com janela de 12h (nao some: IMAP morto por senha errada precisa chegar ao Thiago)
const silencioso = !!trig && /email/i.test(wfName);
const janela = silencioso ? '12 hours' : '30 minutes';
let sql =
  "SELECT pg_advisory_xact_lock(hashtext('alerta_" + esc(wfName) + "'));\n" +   // serializa handlers concorrentes (evita alerta duplicado)
  "INSERT INTO giulia_erros_log (workflow, node, mensagem) VALUES ('" + esc(wfName) + "', '" + esc(node) + "', '" + esc(msg) + "');\n";
const texto = silencioso
  ? "'⚠️ O trigger de e-mail do " + esc(wfName) + " caiu ' || (SELECT count(*) FROM giulia_erros_log WHERE workflow = '" + esc(wfName) + "' AND criado_em > NOW() - INTERVAL '12 hours')::text || ' vez(es) nas ultimas 12h (o n8n reconecta sozinho). Se os e-mails pararem de chegar, confere a credencial IMAP no n8n.'"
  : "'⚠️ ' || (SELECT count(*) FROM giulia_erros_log WHERE workflow = '" + esc(wfName) + "' AND criado_em > NOW() - INTERVAL '30 minutes')::text || ' erro(s) no " + esc(wfName) + " na ultima meia hora. Ultimo (node " + esc(node) + "): " + esc(msg) + ". Exec " + esc(execId) + ". Se seguir aparecendo, olha o servidor.'";
sql +=
  "INSERT INTO giulia_mensagens_agendadas (destinatario_numero, destinatario_nome, conteudo, agendado_para, status) " +
  "SELECT '5511910441709', 'Thiago', " + texto + ", " +
  "NOW() AT TIME ZONE 'America/Sao_Paulo', 'pendente' " +
  "WHERE NOT EXISTS (SELECT 1 FROM giulia_mensagens_agendadas WHERE destinatario_numero = '5511910441709' " +
  "AND conteudo LIKE '⚠️%" + wfLike + "%' AND criado_em > NOW() - INTERVAL '" + janela + "');";
return [{ json: { sql, alerta: wfName + ': ' + msg, silencioso } }];
